import { sql } from 'drizzle-orm';
import { timestamp, uuid } from 'drizzle-orm/pg-core';

/**
 * Shared column helpers. Domain tables use UUID primary keys generated by the
 * application (UUIDv7, time-ordered) with a database default as a fallback.
 * Auth tables managed by Better Auth use text ids (its own generator).
 */

export const uuidPk = () =>
  uuid('id')
    .primaryKey()
    .default(sql`gen_random_uuid()`);

export const timestamps = {
  createdAt: timestamp('created_at', { withTimezone: true, mode: 'date' }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true, mode: 'date' })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
};

/**
 * RLS predicate used by every tenant-scoped table. The application role sets
 * `app.org_id` with `SET LOCAL` inside a transaction (see client.ts); with
 * no setting, `current_setting(..., true)` returns NULL and the policy denies.
 */
export const tenantPredicate = (column: string) =>
  sql.raw(`${column} = current_setting('app.org_id', true)`);
